#include <stdio.h>

typedef struct {
    int pid, arrival, burst, completion, turnaround, waiting;
} Process;

int main() {
    Process p[] = {{1, 0, 5}, {2, 1, 3}, {3, 2, 8}, {4, 3, 6}};
    int n = 4, time = 0;
    double totalWaiting = 0, totalTurnaround = 0;

    printf("FCFS Gantt Chart\n");
    for (int i = 0; i < n; i++) {
        if (time < p[i].arrival) {
            time = p[i].arrival;
        }
        int start = time;
        time += p[i].burst;
        p[i].completion = time;
        p[i].turnaround = p[i].completion - p[i].arrival;
        p[i].waiting = p[i].turnaround - p[i].burst;
        totalWaiting += p[i].waiting;
        totalTurnaround += p[i].turnaround;
        printf("P%d: %d -> %d\n", p[i].pid, start, p[i].completion);
    }

    printf("\nPID AT BT CT TAT WT\n");
    for (int i = 0; i < n; i++) {
        printf("P%d  %d  %d  %d  %d   %d\n", p[i].pid, p[i].arrival, p[i].burst,
        p[i].completion, p[i].turnaround, p[i].waiting);
    }
    printf("Average Waiting Time: %.2f\n", totalWaiting / n);
    printf("Average Turnaround Time: %.2f\n", totalTurnaround / n);

    printf("\nLab No.: 1(a)\n");
    printf("Name: {NAME}\n");
    printf("Roll No./Section: {ROLL}/{SECTION}\n");

    return 0;
}

#include <stdio.h>

void printFrames(int frames[], int n) {
    printf("[");
    for (int i = 0; i < n; i++) {
        if (frames[i] == -1) {
            printf("-");
        }
        else {
            printf("%d", frames[i]);
        }
        if (i + 1 != n) {
            printf(" ");
        }
    }
    printf("]");
}

int main() {
    int pages[] = {7, 0, 1, 2, 0, 3, 0, 4, 2, 3, 0, 3, 2};
    int frames[3] = {-1, -1, -1};
    int n = 13, pointer = 0, faults = 0, hits = 0;
    printf("FIFO Page Replacement\n");
    for (int i = 0; i < n; i++) {
        int page = pages[i], hit = 0;
        for (int j = 0; j < 3; j++) {
            if (frames[j] == page) {
                hit = 1;
            }
        }
        if (hit) {
            hits++;
        }
        else {
            faults++;
            frames[pointer] = page;
            pointer = (pointer + 1) % 3;
        }
        printf("Page %2d -> ", page);
        printFrames(frames, 3);
        printf("%s\n", hit ? " Hit" : " Fault");
    }
    printf("Total Page Faults: %d\nTotal Page Hits: %d\n", faults, hits);

    printf("\nLab No.: 3(a)\n");
    printf("Name: {NAME}\n");
    printf("Roll No./Section: {ROLL}/{SECTION}\n");

    return 0;
}
